c=sqlite3.connect("file:/data/watch.db?mode=ro",uri=True)
def one(q,a):
    r=c.execute(q,a).fetchone(); return r[0] if r else None
fund=lambda w: one("select funder from watch_wallets where wallet=?",(w,))
